const T17_M_M2H: SatQuestion[] = [
  { id: "t17m2h-1", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 64 = 0 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: solve for the positive root. Add 64 to get x² = 64, so x = ±8. Since the problem requires x > 0, take x = 8. The trap is reporting −8 or both roots when only the positive one is asked for." },
  { id: "t17m2h-2", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 2x + 3y = 20 and x − 3y = 1, what is the value of x?", type: "mcq", choices: ["7", "6", "8", "3"], correct: 0, explanation: "Goal: solve the system for x. Adding the two equations eliminates y: (2x + 3y) + (x − 3y) = 20 + 1, giving 3x = 21, so x = 7. The trap is subtracting the equations, which would not cancel the y terms." },
  { id: "t17m2h-3", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 5^x = 125, what is the value of x?", type: "grid", gridAnswers: ["3"], explanation: "Goal: solve the exponential equation. Express 125 as a power of 5: 125 = 5³. Since the bases match, x = 3. The trap is dividing 125 by 5 instead of recognizing the power." },
  { id: "t17m2h-4", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A coat originally priced at $90 is marked up by 30%. What is the new price?", type: "mcq", choices: ["$117", "$120", "$63", "$108"], correct: 0, explanation: "Goal: find the marked-up price. Compute 30% of 90 = 0.30 × 90 = 27. Add it to the original: 90 + 27 = $117. The trap is taking 30% of the wrong base or subtracting instead of adding." },
  { id: "t17m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A right triangle has legs of length 9 and 12. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["15"], explanation: "Goal: apply the Pythagorean theorem. Compute the squares: 9² + 12² = 81 + 144 = 225. Take the square root: √225 = 15. The trap is adding the legs (9 + 12 = 21) instead of using their squares." },
  { id: "t17m2h-6", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If p(x) = 3x − 2, what is the value of p(p(4))?", type: "mcq", choices: ["28", "10", "30", "34"], correct: 0, explanation: "Goal: apply the function twice. First p(4) = 3(4) − 2 = 10. Then p(10) = 3(10) − 2 = 28. The trap is stopping at p(4) = 10 instead of feeding it back into p." },
  { id: "t17m2h-7", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 3x + 2y = 17 and x = y + 1, what is the value of y?", type: "grid", gridAnswers: ["2.8", "14/5"], explanation: "Goal: solve the system by substitution. Replace x with y + 1: 3(y + 1) + 2y = 17, which gives 3y + 3 + 2y = 17, so 5y + 3 = 17. Then 5y = 14 and y = 14/5 = 2.8. The trap is mis-distributing the 3 across (y + 1)." },
  { id: "t17m2h-8", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The parabola y = x² − 8x + 12 has its vertex at (h, k). What is the value of h?", type: "grid", gridAnswers: ["4"], explanation: "Goal: find the x-coordinate of the vertex. Use h = −b/(2a) with a = 1 and b = −8, giving h = −(−8)/(2·1) = 8/2 = 4. The trap is dropping the negative sign and getting −4." },
  { id: "t17m2h-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "In a right triangle, an acute angle θ has cos θ = 8/17. What is sin θ?", type: "mcq", choices: ["15/17", "8/15", "17/15", "15/8"], correct: 0, explanation: "Goal: find sin θ from cos θ. With adjacent 8 and hypotenuse 17, find the opposite leg: √(17² − 8²) = √(289 − 64) = √225 = 15. So sin θ = opposite/hypotenuse = 15/17. This is the 8-15-17 Pythagorean triple; the trap is using 8/15, which is the tangent." },
  { id: "t17m2h-10", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + bx + 25 is a perfect square trinomial and b > 0, what is the value of b?", type: "grid", gridAnswers: ["10"], explanation: "Goal: match the trinomial to a perfect square. A perfect square (x + a)² = x² + 2ax + a² needs a² = 25, so a = 5 (taking the positive value since b > 0). Then b = 2a = 10. The trap is answering 5 instead of doubling it." },
  { id: "t17m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "A line has slope −3 and passes through (2, 5). What is its y-intercept?", type: "mcq", choices: ["11", "−1", "5", "−3"], correct: 0, explanation: "Goal: find b in y = mx + b. Substitute the point and slope: 5 = −3(2) + b, so 5 = −6 + b. Add 6 to both sides to get b = 11. The trap is mishandling the negative sign and getting −1." },
  { id: "t17m2h-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "After a 25% discount, a tablet costs $300. What was the original price?", type: "mcq", choices: ["$400", "$375", "$325", "$240"], correct: 0, explanation: "Goal: recover the original price. After a 25% discount, the price is 75% of the original, so 300 = 0.75 × original. Divide: original = 300 / 0.75 = $400. The trap is adding 25% to $300 (giving $375) instead of dividing by 0.75." },
  { id: "t17m2h-13", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² and f(a) = 49 with a < 0, what is the value of a?", type: "grid", gridAnswers: ["-7"], explanation: "Goal: find the negative root. Since f(a) = a² = 49, a = ±7. The condition a < 0 forces a = −7. The trap is reporting 7 and ignoring the requirement that a be negative." },
  { id: "t17m2h-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has radius 4 and height 6. What is its volume, in terms of π?", type: "mcq", choices: ["96π", "48π", "24π", "144π"], correct: 0, explanation: "Goal: find the cylinder's volume. Use V = πr²h with r = 4 and h = 6: V = π(4²)(6) = π(16)(6) = 96π. The trap is forgetting to square the radius and computing π(4)(6) = 24π." },
  { id: "t17m2h-15", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 1/x + 1/4 = 1, what is the value of x?", type: "grid", gridAnswers: ["1.333", "4/3"], explanation: "Goal: solve for x. Isolate 1/x: 1/x = 1 − 1/4 = 3/4. Take the reciprocal of both sides: x = 4/3 ≈ 1.333. The trap is taking x = 3/4 without flipping the fraction." },
  { id: "t17m2h-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "What is the product of the solutions to x² − 7x + 10 = 0?", type: "mcq", choices: ["10", "7", "−10", "3"], correct: 0, explanation: "Goal: find the product of the roots. Factor as (x − 2)(x − 5) = 0, giving roots 2 and 5 whose product is 10. Equivalently, the product of roots equals c/a = 10/1 = 10. The trap is reporting the sum (7) instead of the product." },
  { id: "t17m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The ratio of red to blue tiles is 2:7. If there are 63 tiles in all, how many are blue?", type: "mcq", choices: ["49", "14", "45", "56"], correct: 0, explanation: "Goal: split the total by the ratio. The parts add to 2 + 7 = 9, so each part is 63 ÷ 9 = 7 tiles. Blue gets 7 parts: 7 × 7 = 49. The trap is finding the red count (2 × 7 = 14) instead of the blue count." },
  { id: "t17m2h-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have a scale factor of 1:4. If the smaller has area 5, what is the area of the larger?", type: "grid", gridAnswers: ["80"], explanation: "Goal: scale the area. Areas of similar figures scale by the square of the linear ratio, so the factor is 4² = 16. Multiply: 5 × 16 = 80. The trap is multiplying by 4 instead of 4², giving 20." },
  { id: "t17m2h-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If √(x + 5) = 6, what is the value of x?", type: "grid", gridAnswers: ["31"], explanation: "Goal: solve the radical equation. Square both sides to remove the root: x + 5 = 6² = 36. Subtract 5 to get x = 31. The trap is forgetting to square the 6 and getting x = 1." },
  { id: "t17m2h-20", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 5x − 2y = 24 and y = 3, what is the value of x?", type: "mcq", choices: ["6", "5", "4", "30"], correct: 0, explanation: "Goal: solve for x after substitution. Replace y with 3: 5x − 2(3) = 24, so 5x − 6 = 24. Add 6 to get 5x = 30, then divide by 5 to get x = 6. The trap is dividing 24 by 5 before handling the −6." },
  { id: "t17m2h-21", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If g(x) = x² − 6x + 9, for what value of x does g(x) = 0?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the root of the quadratic. Factor: x² − 6x + 9 = (x − 3)², which equals 0 only when x − 3 = 0, so x = 3. The trap is expecting two distinct roots when this perfect square has a single repeated root." },
  { id: "t17m2h-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A population of insects triples every day. If it starts at 20, how many are there after 3 days?", type: "mcq", choices: ["540", "180", "60", "1620"], correct: 0, explanation: "Goal: apply exponential growth. After 3 days the population is 20 × 3³ = 20 × 27 = 540. The trap is multiplying by 3 only once (60) or by 3 × 3 = 9 (180) instead of 3³." },
];

